  8	func TestParse(t *testing.T) {
  9		tests := []struct {
 10			in, code string
 11			want     int64
 12			wantErr  error
 13		}{
 14			{"10.50", "USD", 1050, nil},
 15			{"10.5", "USD", 1050, nil},
 16			{"10", "USD", 1000, nil},
 17			{"0.01", "eur", 1, nil},
 18			{"-3.25", "BRL", -325, nil},
 19			{"10.005", "USD", 0, ErrPrecision},
 20			{"abc", "USD", 0, ErrInvalidAmount},
 21			{"1.", "USD", 0, ErrInvalidAmount},
 22			{"", "USD", 0, ErrInvalidAmount},
 23			{"1.00", "XXX", 0, ErrUnknownCurrency},
 24			{"99999999999999999999", "USD", 0, ErrInvalidAmount},
 25		}
 26		for _, tt := range tests {
 27			t.Run(tt.in+"_"+tt.code, func(t *testing.T) {
 28				got, err := Parse(tt.in, tt.code)
 29				if !errors.Is(err, tt.wantErr) {
 30					t.Fatalf("Parse(%q, %q) error = %v, want %v", tt.in, tt.code, err, tt.wantErr)
 31				}
 32				if err == nil && got.Minor != tt.want {
 33					t.Fatalf("Parse(%q, %q) = %d, want %d", tt.in, tt.code, got.Minor, tt.want)
 34				}
 35			})
 36		}
 37	}
