import (
	"cmp"
	"fmt"
	"math/big"
	"math/bits"
	"slices"
)

// Allocate splits a into len(ratios) parts proportional to ratios, for example
// to pay out one charge to several sub-merchants.
//
// Contract (reconciliation depends on it):
//   - the parts always sum exactly to a;
//   - every part differs from its exact proportional share by less than one
//     minor unit;
//   - leftover minor units go one each to the parts with the largest fractional
//     remainder, ties broken by lower index.
//
// a must be non-negative, ratios non-negative with a positive sum.
func Allocate(a Amount, ratios []int64) ([]Amount, error) {
	if a.Minor < 0 {
		return nil, fmt.Errorf("%w: cannot allocate negative amount %s", ErrInvalidAmount, a)
	}
	var total uint64
	var totalOverflows bool
	for _, r := range ratios {
		if r < 0 {
			return nil, fmt.Errorf("%w: negative ratio %d", ErrInvalidAmount, r)
		}
		var carry uint64
		total, carry = bits.Add64(total, uint64(r), 0)
		if carry != 0 {
			totalOverflows = true
		}
	}
	if !totalOverflows && total == 0 {
		return nil, fmt.Errorf("%w: ratios must sum to a positive value", ErrInvalidAmount)
	}
	if totalOverflows {
		return allocateBig(a, ratios), nil
	}

	n := len(ratios)
	parts := make([]Amount, n)
	rems := make([]uint64, n)
	minor := uint64(a.Minor)
	var allocated int64
	for i, r := range ratios {
		hi, lo := bits.Mul64(minor, uint64(r))
		q, rem := bits.Div64(hi, lo, total)
		parts[i] = Amount{Minor: int64(q), Currency: a.Currency}
		rems[i] = rem
		allocated += int64(q)
	}

	leftover := int(a.Minor - allocated)
	if leftover > 0 {
		order := make([]int, n)
		for i := range order {
			order[i] = i
		}
		slices.SortFunc(order, func(i, j int) int {
			if c := cmp.Compare(rems[j], rems[i]); c != 0 {
				return c
			}
			return cmp.Compare(i, j)
		})
		for i := range leftover {
			parts[order[i]].Minor++
		}
	}
	return parts, nil
}

func allocateBig(a Amount, ratios []int64) []Amount {
	total := new(big.Int)
	var tmp big.Int
	for _, r := range ratios {
		total.Add(total, tmp.SetInt64(r))
	}

	n := len(ratios)
	parts := make([]Amount, n)
	rems := make([]*big.Int, n)
	minor := big.NewInt(a.Minor)
	var allocated int64
	var prod, q big.Int
	for i, r := range ratios {
		prod.Mul(minor, tmp.SetInt64(r))
		rem := new(big.Int)
		q.QuoRem(&prod, total, rem)
		qi := q.Int64()
		parts[i] = Amount{Minor: qi, Currency: a.Currency}
		rems[i] = rem
		allocated += qi
	}

	leftover := int(a.Minor - allocated)
	if leftover > 0 {
		order := make([]int, n)
		for i := range order {
			order[i] = i
		}
		slices.SortFunc(order, func(i, j int) int {
			if c := rems[j].Cmp(rems[i]); c != 0 {
				return c
			}
			return cmp.Compare(i, j)
		})
		for i := range leftover {
			parts[order[i]].Minor++
		}
	}
	return parts
}

