func TestAllocateRemainderAndTieBreaking(t *testing.T) {
	tests := []struct {
		name   string
		amount Amount
		ratios []int64
		want   []int64
	}{
		{
			name:   "100_USD_three_way",
			amount: MustNew(10000, "USD"),
			ratios: []int64{1, 1, 1},
			want:   []int64{3334, 3333, 3333},
		},
		{
			name:   "10_cents_seven_way",
			amount: MustNew(10, "USD"),
			ratios: []int64{1, 1, 1, 1, 1, 1, 1},
			want:   []int64{2, 2, 2, 1, 1, 1, 1},
		},
		{
			name:   "5_cents_two_way",
			amount: MustNew(5, "USD"),
			ratios: []int64{1, 1},
			want:   []int64{3, 2},
		},
		{
			name:   "largest_remainder_at_end",
			amount: MustNew(10, "USD"),
			ratios: []int64{3, 2, 1},
			want:   []int64{5, 3, 2},
		},
		{
			name:   "largest_remainder_at_start",
			amount: MustNew(10, "USD"),
			ratios: []int64{1, 2, 3},
			want:   []int64{2, 3, 5},
		},
		{
			name:   "multiple_leftovers_with_ties",
			amount: MustNew(5, "USD"),
			ratios: []int64{1, 3, 2, 3},
			want:   []int64{0, 2, 1, 2},
		},
		{
			name:   "single_leftover_tie_broken_by_lower_index",
			amount: MustNew(1, "USD"),
			ratios: []int64{1, 3, 2, 3},
			want:   []int64{0, 1, 0, 0},
		},
		{
			name:   "equal_exact_remainders_float_precision_trap",
			amount: MustNew(2, "USD"),
			ratios: []int64{4, 1, 1},
			want:   []int64{2, 0, 0},
		},
		{
			name:   "zero_amount",
			amount: MustNew(0, "USD"),
			ratios: []int64{1, 2, 3},
			want:   []int64{0, 0, 0},
		},
		{
			name:   "zero_ratios_mixed",
			amount: MustNew(5, "USD"),
			ratios: []int64{0, 1, 0, 1},
			want:   []int64{0, 3, 0, 2},
		},
		{
			name:   "jpy_exponent_zero",
			amount: MustNew(100, "JPY"),
			ratios: []int64{1, 1, 1},
			want:   []int64{34, 33, 33},
		},
		{
			name:   "kwd_exponent_three",
			amount: MustNew(1000, "KWD"),
			ratios: []int64{1, 1, 1},
			want:   []int64{334, 333, 333},
