func verifyAllocateContract(t *testing.T, a Amount, ratios []int64, parts []Amount) {
	t.Helper()
	if len(parts) != len(ratios) {
		t.Fatalf("len(parts) = %d, want %d", len(parts), len(ratios))
	}

	var sum int64
	for i, p := range parts {
		if p.Currency != a.Currency {
			t.Fatalf("part[%d] currency = %v, want %v", i, p.Currency, a.Currency)
		}
		if p.Minor < 0 {
			t.Fatalf("part[%d] negative: %d", i, p.Minor)
		}
		sum += p.Minor
	}
	if sum != a.Minor {
		t.Fatalf("sum(parts) = %d, want %d", sum, a.Minor)
	}

	total := new(big.Int)
	for _, r := range ratios {
		total.Add(total, big.NewInt(r))
	}

	one := big.NewRat(1, 1)
	minorBig := big.NewInt(a.Minor)
	fracs := make([]*big.Rat, len(ratios))
	roundedUp := make([]bool, len(ratios))

	for i, r := range ratios {
		num := new(big.Int).Mul(minorBig, big.NewInt(r))
		exact := new(big.Rat).SetFrac(num, total)
		got := new(big.Rat).SetInt64(parts[i].Minor)
		diff := new(big.Rat).Sub(got, exact)
		absDiff := new(big.Rat).Abs(diff)
		if absDiff.Cmp(one) >= 0 {
			t.Fatalf("part[%d] = %d differs from exact share %s by %s (>= 1)", i, parts[i].Minor, exact.RatString(), absDiff.RatString())
		}

		quo, rem := new(big.Int).QuoRem(num, total, new(big.Int))
		floor := quo.Int64()
		fracs[i] = new(big.Rat).SetFrac(rem, total)
		switch parts[i].Minor {
		case floor:
			roundedUp[i] = false
		case floor + 1:
			roundedUp[i] = true
		default:
			t.Fatalf("part[%d] = %d, expected floor %d or floor+1 %d", i, parts[i].Minor, floor, floor+1)
		}
	}

	// Verify largest-remainder + lower-index tie-breaking:
	// every rounded-up index i and non-rounded-up index j must satisfy
	// fracs[i] > fracs[j], or (fracs[i] == fracs[j] && i < j).
	for i := range parts {
		if !roundedUp[i] {
			continue
		}
		for j := range parts {
			if roundedUp[j] {
				continue
			}
			c := fracs[i].Cmp(fracs[j])
			if c < 0 || (c == 0 && i > j) {
				t.Fatalf("tie/order violation: index %d (frac %s) rounded up while index %d (frac %s) did not",
					i, fracs[i].RatString(), j, fracs[j].RatString())
			}
		}
	}
}

