  4		"cmp"
  5		"fmt"
  6		"math/big"
  7		"math/bits"
  8		"slices"
  9	)
 10	
 11	// Allocate splits a into len(ratios) parts proportional to ratios, for example
 12	// to pay out one charge to several sub-merchants.
 13	//
 14	// Contract (reconciliation depends on it):
 15	//   - the parts always sum exactly to a;
 16	//   - every part differs from its exact proportional share by less than one
 17	//     minor unit;
 18	//   - leftover minor units go one each to the parts with the largest fractional
 19	//     remainder, ties broken by lower index.
 20	//
 21	// a must be non-negative, ratios non-negative with a positive sum.
 22	func Allocate(a Amount, ratios []int64) ([]Amount, error) {
 23		if a.Minor < 0 {
 24			return nil, fmt.Errorf("%w: cannot allocate negative amount %s", ErrInvalidAmount, a)
 25		}
 26		var total uint64
 27		var totalOverflows bool
 28		for _, r := range ratios {
 29			if r < 0 {
 30				return nil, fmt.Errorf("%w: negative ratio %d", ErrInvalidAmount, r)
 31			}
 32			var carry uint64
 33			total, carry = bits.Add64(total, uint64(r), 0)
 34			if carry != 0 {
 35				totalOverflows = true
 36			}
 37		}
 38		if !totalOverflows && total == 0 {
 39			return nil, fmt.Errorf("%w: ratios must sum to a positive value", ErrInvalidAmount)
 40		}
 41		if totalOverflows {
 42			return allocateBig(a, ratios), nil
 43		}
 44	
 45		n := len(ratios)
 46		parts := make([]Amount, n)
 47		rems := make([]uint64, n)
 48		minor := uint64(a.Minor)
 49		var allocated int64
 50		for i, r := range ratios {
 51			hi, lo := bits.Mul64(minor, uint64(r))
 52			q, rem := bits.Div64(hi, lo, total)
 53			parts[i] = Amount{Minor: int64(q), Currency: a.Currency}
 54			rems[i] = rem
 55			allocated += int64(q)
 56		}
 57	
 58		leftover := int(a.Minor - allocated)
 59		if leftover > 0 {
 60			order := make([]int, n)
 61			for i := range order {
 62				order[i] = i
 63			}
 64			slices.SortFunc(order, func(i, j int) int {
 65				if c := cmp.Compare(rems[j], rems[i]); c != 0 {
 66					return c
 67				}
 68				return cmp.Compare(i, j)
 69			})
 70			for i := range leftover {
 71				parts[order[i]].Minor++
 72			}
 73		}
 74		return parts, nil
 75	}
 76	
 77	func allocateBig(a Amount, ratios []int64) []Amount {
 78		total := new(big.Int)
 79		var tmp big.Int
 80		for _, r := range ratios {
 81			total.Add(total, tmp.SetInt64(r))
 82		}
 83	
 84		n := len(ratios)
 85		parts := make([]Amount, n)
 86		rems := make([]*big.Int, n)
 87		minor := big.NewInt(a.Minor)
 88		var allocated int64
 89		var prod, q big.Int
 90		for i, r := range ratios {
 91			prod.Mul(minor, tmp.SetInt64(r))
 92			rem := new(big.Int)
 93			q.QuoRem(&prod, total, rem)
 94			qi := q.Int64()
 95			parts[i] = Amount{Minor: qi, Currency: a.Currency}
 96			rems[i] = rem
 97			allocated += qi
 98		}
 99	
100		leftover := int(a.Minor - allocated)
101		if leftover > 0 {
102			order := make([]int, n)
103			for i := range order {
104				order[i] = i
105			}
106			slices.SortFunc(order, func(i, j int) int {
107				if c := rems[j].Cmp(rems[i]); c != 0 {
108					return c
109				}
110				return cmp.Compare(i, j)
111			})
112			for i := range leftover {
113				parts[order[i]].Minor++
114			}
115		}
116		return parts
117	}

